package com.shopsphere.dao;
import com.shopsphere.model.*;
import com.shopsphere.util.DBConnection;
import java.sql.*;
import java.util.*;
public class WishlistDAO {
    public List<WishlistItem> findByUserId(Long userId) { List<WishlistItem> l = new ArrayList<>(); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT w.id AS wishlist_id, w.user_id, w.product_id, w.created_at, p.name, p.brand, p.price, p.discount, p.stock, p.image_url, p.status, c.name AS category_name FROM wishlist w JOIN products p ON w.product_id=p.id JOIN categories c ON p.category_id=c.id WHERE w.user_id=? ORDER BY w.id DESC")) { p.setLong(1, userId); try (ResultSet r = p.executeQuery()) { while (r.next()) { WishlistItem wi = new WishlistItem(); wi.setId(r.getLong("wishlist_id")); wi.setUserId(r.getLong("user_id")); wi.setProductId(r.getLong("product_id")); Product pr = new Product(); pr.setId(wi.getProductId()); pr.setName(r.getString("name")); pr.setBrand(r.getString("brand")); pr.setPrice(r.getBigDecimal("price")); pr.setDiscount(r.getBigDecimal("discount")); pr.setStock(r.getInt("stock")); pr.setImageUrl(r.getString("image_url")); pr.setStatus(Product.Status.valueOf(r.getString("status"))); pr.setCategoryName(r.getString("category_name")); wi.setProduct(pr); l.add(wi); } } } catch (SQLException e) {} return l; }
    public boolean add(Long userId, Long prodId) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("INSERT IGNORE INTO wishlist (user_id,product_id) VALUES (?,?)")) { p.setLong(1, userId); p.setLong(2, prodId); return p.executeUpdate() > 0; } catch (SQLException e) { return false; } }
    public boolean remove(Long userId, Long prodId) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("DELETE FROM wishlist WHERE user_id=? AND product_id=?")) { p.setLong(1, userId); p.setLong(2, prodId); return p.executeUpdate() > 0; } catch (SQLException e) { return false; } }
    public boolean isProductInWishlist(Long userId, Long prodId) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT 1 FROM wishlist WHERE user_id=? AND product_id=?")) { p.setLong(1, userId); p.setLong(2, prodId); try (ResultSet r = p.executeQuery()) { return r.next(); } } catch (SQLException e) { return false; } }
}
